insert.foreach:
INSERT INTO 
	웹주문접수
		(
			접수일자
			, 일련번호
			, 장바구니일자
			, 등록구분
			, 단가사업장
			, 거래처코드
			, 품목코드
			, 단가단위
			, 단가단위문자
			, 수량
			, 그룹수량
			, 낱개수량
			, 중량
			, 단가
			, 기준단가
			, 공급가액
			, 부가세
			, 합계금액
			, 납기일자
			, 주문비고
			, 착지업체
			, 출고사업장
			, 주문사업장
			, 주문일자
			, 주문번호
			, 등록자
			, 등록일자
			, 등록시간
			, 수정자
			, 수정일자
			, 수정시간
	)
	VALUES(
			CONVERT(VARCHAR,GETDATE(),112) 
			, (SELECT ISNULL(MAX(일련번호+1),1) FROM 웹주문접수 WHERE 1=1 AND 접수일자 = #{oDate}) 
			, #{oDate}
			, 'M' 
			, #{item.oUnitBplc} 
			, #{item.oBcncCode} 
			, #{item.oItemCode} 
			, #{item.oUntpcUnit} 
			, #{item.oUnitChrctr}	
			, #{item.oQuantity} 
			, #{item.oGrpQy} 
			, #{item.oPieceQy} 
			, #{item.oWt} 
			, #{item.oNewUnitpc} 
			, #{item.oStdrUnitpc} 
			, #{item.oSplpcAm} 
			, #{item.oVat} 
			, #{item.oSumAm} 
			, #{item.oItemDedt} 
			, #{item.oRm} 
			, #{item.oDlvyEntrps} 
			, (SELECT 출고사업장 FROM 업체배송지등록 WHERE 업체코드 = #{item.oBcncCode} AND 착지업체= #{item.oDlvyEntrps} AND 출고사업장 = #{ordBplc})
			, #{registBplc} 
			, CONVERT(VARCHAR,GETDATE(),112) 
			, (SELECT ISNULL(MAX(주문번호+1),1) FROM 웹주문접수 WHERE 1=1 AND 주문일자 = CONVERT(VARCHAR,GETDATE(),112)) 
			, #{bcncCode} 
			, CONVERT(VARCHAR,GETDATE(),112) 
			, REPLACE(CONVERT(VARCHAR,GETDATE(),108),':','') 
			, #{bcncCode} 
			, CONVERT(VARCHAR,GETDATE(),112) 
			, REPLACE(CONVERT(VARCHAR,GETDATE(),108),':','') 
	)
